{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client') OR (service_name='rate' AND span_name='rate.Rate/GetRates') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "search's client spans to rate take p50 ~1799 ms, while rate's server spans stay at p50 ~0.13 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE (service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client') OR (service_name='rate' AND span_name='rate.Rate/GetRates') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Before the incident the same search-to-rate client spans had p50 ~3.3 ms, so the added time is new in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "search's client spans to geo stay at p50 ~0.4 ms, so the delay is specific to the search-to-rate connection."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, ROUND(AVG(value),4) avgv FROM abnormal_metrics_sum WHERE service_name IN ('search','rate') AND metric IN ('k8s.pod.uptime','container.cpu.time') GROUP BY 1,2",
          "claim": "search and rate show no restarts (uptime keeps rising) and no CPU saturation; their CPU time stays near normal levels."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) OR (service_name='search' AND span_name='search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "search's server spans reach p50 ~1799 ms and frontend's search client and HTTP /hotels spans show ~1770 ms p50, so the delay passes straight up to users."
        }
      ]
    }
  ]
}
